#[public]
impl IErc20 for Erc20 {
    type Error = Error;

    fn total_supply(&self) -> U256 {
        self.total_supply.get()
    }

    fn balance_of(&self, account: Address) -> U256 {
        self.balances.get(account)
    }

    fn transfer(
        &mut self,
        to: Address,
        value: U256,
    ) -> Result<bool, Self::Error> {
        let from = self.vm().msg_sender();
        self._transfer(from, to, value)?;
        Ok(true)
    }

    fn allowance(&self, owner: Address, spender: Address) -> U256 {
        self.allowances.get(owner).get(spender)
    }

    fn approve(
        &mut self,
        spender: Address,
        value: U256,
    ) -> Result<bool, Self::Error> {
        let owner = self.vm().msg_sender();
        self._approve(owner, spender, value, true)
    }

    fn transfer_from(
        &mut self,
        from: Address,
        to: Address,
        value: U256,
    ) -> Result<bool, Self::Error> {
        let spender = self.vm().msg_sender();
        self._spend_allowance(from, spender, value)?;
        self._transfer(from, to, value)?;
        Ok(true)
    }
}

impl Erc20 {
    /// Sets a `value` number of tokens as the allowance of `spender` over the
    /// caller's tokens.
    ///
    /// Returns a boolean value indicating whether the operation succeeded.
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `owner` - Account that owns the tokens.
    /// * `spender` - Account that will spend the tokens.
    /// * `emit_event` - Emit an [`Approval`] event flag.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSpender`] - If the `spender` address is
    ///   [`Address::ZERO`].
    ///
    /// # Events
    ///
    /// * [`Approval`].
    fn _approve(
        &mut self,
        owner: Address,
        spender: Address,
        value: U256,
        emit_event: bool,
    ) -> Result<bool, Error> {
        if owner.is_zero() {
            return Err(Error::InvalidApprover(ERC20InvalidApprover {
                approver: Address::ZERO,
            }));
        }

        if spender.is_zero() {
            return Err(Error::InvalidSpender(ERC20InvalidSpender {
                spender: Address::ZERO,
            }));
        }

        self.allowances.setter(owner).insert(spender, value);
        if emit_event {
            self.vm().log(Approval { owner, spender, value });
        }
        Ok(true)
    }

    /// Internal implementation of transferring tokens between two accounts.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to transfer tokens from.
    /// * `to` - Account to transfer tokens to.
    /// * `value` - The number of tokens to transfer.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSender`] - If the `from` address is [`Address::ZERO`].
    /// * [`Error::InvalidReceiver`] - If the `to` address is [`Address::ZERO`].
    /// * [`Error::InsufficientBalance`] - If the `from` address doesn't have
    ///   enough tokens.
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    fn _transfer(
        &mut self,
        from: Address,
        to: Address,
        value: U256,
    ) -> Result<(), Error> {
        if from.is_zero() {
            return Err(Error::InvalidSender(ERC20InvalidSender {
                sender: Address::ZERO,
            }));
        }
        if to.is_zero() {
            return Err(Error::InvalidReceiver(ERC20InvalidReceiver {
                receiver: Address::ZERO,
            }));
        }

        self._update(from, to, value)?;

        Ok(())
    }

    /// Creates a `value` amount of tokens and assigns them to `account`,
    /// by transferring it from [`Address::ZERO`].
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] - If the `account` address is
    ///   [`Address::ZERO`].
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    ///
    /// # Panics
    ///
    /// * If `total_supply` exceeds [`U256::MAX`].
    pub fn _mint(
        &mut self,
        account: Address,
        value: U256,
    ) -> Result<(), Error> {
        if account.is_zero() {
            return Err(Error::InvalidReceiver(ERC20InvalidReceiver {
                receiver: Address::ZERO,
            }));
        }
        self._update(Address::ZERO, account, value)
    }

    /// Transfers a `value` amount of tokens from `from` to `to`, or

output.text:
    ///
    /// * [`erc20::Transfer`].
    /// * [`erc20::Approval`].
    ///
    /// # Panics
    ///
    /// * If the new (temporary) total supply exceeds [`U256::MAX`].
    /// * If the sum of the loan value and fee exceeds the maximum value of
    ///   [`U256::MAX`].
    fn flash_loan(
        &mut self,
        receiver: Address,
        token: Address,
        value: U256,
        data: Bytes,
    ) -> Result<bool, Self::Error>;
}

impl Erc20FlashMint {
    /// See [`IErc3156FlashLender::max_flash_loan`].
    #[must_use]
    pub fn max_flash_loan(&self, token: Address, erc20: &erc20::Erc20) -> U256 {
        if token == self.vm().contract_address() {
            U256::MAX - erc20.total_supply()
        } else {
            U256::MIN
        }
    }

    /// See [`IErc3156FlashLender::flash_fee`].
    #[allow(clippy::missing_errors_doc)]
    pub fn flash_fee(
        &self,
        token: Address,
        _value: U256,
    ) -> Result<U256, Error> {
        if token == self.vm().contract_address() {
            Ok(self.flash_fee_value.get())
        } else {
            Err(Error::UnsupportedToken(ERC3156UnsupportedToken { token }))
        }
    }

    // This function can reenter, but it doesn't pose a risk because it always
    // preserves the property that the amount minted at the beginning is always
    // recovered and burned at the end, or else the entire function will revert.
    /// See [`IErc3156FlashLender::flash_loan`].
    #[allow(clippy::missing_panics_doc, clippy::missing_errors_doc)]
    pub fn flash_loan(
        &mut self,
        receiver: Address,
        token: Address,
        value: U256,
        data: &Bytes,
        erc20: &mut Erc20,
    ) -> Result<bool, Error> {
        let max_loan = self.max_flash_loan(token, erc20);
        if value > max_loan {
            return Err(Error::ExceededMaxLoan(ERC3156ExceededMaxLoan {
                max_loan,
            }));
        }

        let fee = self.flash_fee(token, value)?;
        if self.vm().code_size(receiver) == 0 {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }
        erc20._mint(receiver, value)?;
        let loan_receiver = IERC3156FlashBorrower::new(receiver);
        let vm = self.vm().clone();
        let loan_return = loan_receiver
            .on_flash_loan(
                &vm,
                Call::new_mutating(self),
                self.vm().msg_sender(),
                token,
                value,
                fee,
                data.to_vec().into(),
            )
            .map_err(|_| {
                Error::ERC3156InvalidReceiver(ERC3156InvalidReceiver {
                    receiver,
                })
            })?;
        if loan_return != BORROWER_CALLBACK_VALUE {
            return Err(Error::ERC3156InvalidReceiver(
                ERC3156InvalidReceiver { receiver },
            ));
        }

        let allowance = value
            .checked_add(fee)
            .expect("allowance should not exceed `U256::MAX`");
        erc20._spend_allowance(
            receiver,
            self.vm().contract_address(),
            allowance,
        )?;

        let flash_fee_receiver = self.flash_fee_receiver_address.get();

        if fee.is_zero() || flash_fee_receiver.is_zero() {
            erc20._burn(receiver, allowance)?;
        } else {
            erc20._burn(receiver, value)?;
            erc20._transfer(receiver, flash_fee_receiver, fee)?;
        }

        Ok(true)
    }
}

