/// State of an [`Erc721Enumerable`] contract.
#[storage]
pub struct Erc721Enumerable {
    /// Maps owners to a mapping of indices to tokens ids.
    pub(crate) owned_tokens: StorageMap<Address, StorageMap<U256, StorageU256>>,
    /// Maps tokens ids to indices in `owned_tokens`.
    pub(crate) owned_tokens_index: StorageMap<U256, StorageU256>,
    /// Stores all tokens ids.
    pub(crate) all_tokens: StorageVec<StorageU256>,
    /// Maps indices at `all_tokens` to tokens ids.
    pub(crate) all_tokens_index: StorageMap<U256, StorageU256>,
}

/// This is the interface of the optional `Enumerable` extension
/// of the ERC-721 standard.
#[interface_id]
pub trait IErc721Enumerable {
    /// The error type associated to this ERC-721 enumerable trait
    /// implementation.
    type Error: Into<alloc::vec::Vec<u8>>;

    /// Returns a token ID owned by `owner` at a given `index` of its token
    /// list.
    ///
    /// Use along with [`super::super::Erc721::balance_of`] to enumerate all of
    /// `owner`'s tokens.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `owner` - Address of token's owner.
    /// * `index` - Index of the token at `owner`'s tokens list.
    ///
    /// # Errors
    ///
    /// * [`Error::OutOfBoundsIndex`] - If an `owner`'s token query is out of
    ///   bounds for `index`.
    fn token_of_owner_by_index(
        &self,
        owner: Address,
        index: U256,
    ) -> Result<U256, Self::Error>;

    /// Returns the total amount of tokens stored by the contract.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn total_supply(&self) -> U256;

    /// Returns a token ID at a given `index` of all the tokens
    /// stored by the contract.
    ///
    /// Use along with [`Self::total_supply`] to
    /// enumerate all tokens.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `index` - Index of the token in all tokens list.
    ///
    /// # Errors
    ///
    /// * [`Error::OutOfBoundsIndex`] - If an `owner`'s token query is out of
    ///   bounds for `index`.
    fn token_by_index(&self, index: U256) -> Result<U256, Self::Error>;
}

#[public]
#[implements(IErc721Enumerable<Error = Error>, IErc165)]
impl Erc721Enumerable {}

#[public]
impl IErc721Enumerable for Erc721Enumerable {
    type Error = Error;

    fn token_of_owner_by_index(
        &self,
        owner: Address,
        index: U256,
    ) -> Result<U256, Self::Error> {
        let token = self.owned_tokens.getter(owner).get(index);

        if token.is_zero() {
            Err(ERC721OutOfBoundsIndex { owner, index }.into())
        } else {
            Ok(token)
        }
    }

    fn total_supply(&self) -> U256 {
        let tokens_length = self.all_tokens.len();
        U256::from(tokens_length)
    }

    fn token_by_index(&self, index: U256) -> Result<U256, Self::Error> {
        self.all_tokens.get(index).ok_or(
            ERC721OutOfBoundsIndex { owner: Address::ZERO, index }.into(),
        )
    }
}

#[public]
impl IErc165 for Erc721Enumerable {
    fn supports_interface(&self, interface_id: B32) -> bool {
        <Self as IErc721Enumerable>::interface_id() == interface_id
            || <Self as IErc165>::interface_id() == interface_id
    }
}

impl Erc721Enumerable {
    /// Function to add a token to this extension's
    /// ownership-tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Address representing the new owner of the given `token_id`.
    /// * `token_id` - ID of the token to be added to the tokens list of the
    ///   given address.
    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
    ///
    /// # Errors
    ///
    /// * [`erc721::Error::InvalidOwner`] - If owner address is
    ///   [`Address::ZERO`].
    pub fn _add_token_to_owner_enumeration(
        &mut self,
        to: Address,
        token_id: U256,
        erc721: &impl IErc721<Error = erc721::Error>,
    ) -> Result<(), erc721::Error> {
        let length = erc721.balance_of(to)? - uint!(1_U256);
        self.owned_tokens.setter(to).setter(length).set(token_id);
        self.owned_tokens_index.setter(token_id).set(length);

        Ok(())
    }

    /// Function to add a token to this extension's token
    /// tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` - ID of the token to be added to the tokens list.
    pub fn _add_token_to_all_tokens_enumeration(&mut self, token_id: U256) {
        let index = self.total_supply();

        self.all_tokens_index.setter(token_id).set(index);
        self.all_tokens.push(token_id);
    }

    /// Function to remove a token from this extension's
    /// ownership-tracking data structures.
    ///
    /// Note that while the token is not assigned a new owner,
    /// the `self.owned_tokens_index` mapping is NOT updated:
    /// this allows for  gas optimizations e.g.
    /// when performing a transfer operation (avoiding double writes).
    ///
    /// This has O(1) time complexity, but alters the order
    /// of the `self.owned_tokens` array.

output.text:
        account: Address,
        token_ids: Vec<U256>,
    ) -> Result<bool, Self::Error>;

    /// Returns the underlying token.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    #[must_use]
    fn underlying(&self) -> Address;
}

impl Erc721Wrapper {
    /// Constructor.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `underlying_token` - The wrapped token.
    pub fn constructor(&mut self, underlying_token: Address) {
        self.underlying.set(underlying_token);
    }

    /// Check [`IErc721Wrapper::deposit_for()`] for more information.
    #[allow(clippy::missing_errors_doc)]
    pub fn deposit_for(
        &mut self,
        account: Address,
        token_ids: Vec<U256>,
        erc721: &mut Erc721,
    ) -> Result<bool, Error> {
        let sender = self.vm().msg_sender();
        let contract_address = self.vm().contract_address();
        let underlying = Erc721Interface::new(self.underlying());
        let vm = self.vm().clone();

        for token_id in token_ids {
            // This is an "unsafe" transfer that doesn't call any hook on
            // the receiver. With [`IErc721Wrapper::underlying()`] being trusted
            // (by design of this contract) and no other contracts expected to
            // be called from there, we are safe.
            match underlying.transfer_from(
                &vm,
                Call::new_mutating(self),
                sender,
                contract_address,
                token_id,
            ) {
                Ok(()) => (),
                Err(e) => {
                    if let stylus_sdk::stylus_core::calls::errors::Error::Revert(ref reason) = e {
                        if !reason.is_empty() {
                            return Err(Error::InvalidReceiverWithReason(
                                erc721::InvalidReceiverWithReason {
                                    reason: String::from_utf8_lossy(reason)
                                        .to_string(),
                                },
                            ));
                        }
                    }
                    return Err(Error::Erc721FailedOperation(
                        Erc721FailedOperation { token: self.underlying() },
                    ));
                }
            }

            erc721._safe_mint(account, token_id, &vec![].into())?;
        }

        Ok(true)
    }

    /// Check [`IErc721Wrapper::withdraw_to()`] for more information.
    #[allow(clippy::missing_errors_doc)]
    pub fn withdraw_to(
        &mut self,
        account: Address,
        token_ids: Vec<U256>,
        erc721: &mut Erc721,
    ) -> Result<bool, Error> {
        let sender = self.vm().msg_sender();
        let contract_address = self.vm().contract_address();
        let underlying = Erc721Interface::new(self.underlying());
        let vm = self.vm().clone();

        for token_id in token_ids {
            // Setting the `auth` argument enables the `_is_authorized` check
            // which verifies that the token exists (from != 0).
            // Therefore, it is not needed to verify that the return value is
            // not 0 here.
            erc721._update(Address::ZERO, token_id, sender)?;
            match underlying.safe_transfer_from(
                &vm,
                Call::new_mutating(self),
                contract_address,
                account,
                token_id,
                vec![].into(),
            ) {
                Ok(()) => (),
                Err(e) => {
                    if let stylus_sdk::stylus_core::calls::errors::Error::Revert(ref reason) = e {
                        if !reason.is_empty() {
                            return Err(Error::InvalidReceiverWithReason(
                                erc721::InvalidReceiverWithReason {
                                    reason: String::from_utf8_lossy(reason)
                                        .to_string(),
                                },
                            ));
                        }
                    }
                    return Err(Error::Erc721FailedOperation(
                        Erc721FailedOperation { token: self.underlying() },
                    ));
                }
            }
        }

        Ok(true)
    }

    /// Allow minting on direct ERC-721 transfers to this contract.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `operator` - The operator of the transfer.
    /// * `from` - The sender of the transfer.
    /// * `token_id` - The token id of the transfer.
    /// * `data` - The data of the transfer.
    /// * `erc721` - Write access to an [`Erc721`] contract.
    ///
    /// # Errors
    ///
    /// * [`Error::UnsupportedToken`] - If the caller is not the underlying
    ///   token.
    /// * [`Error::InvalidSender`] - If `token_id` already exists.
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    /// * [`Error::InvalidReceiver`] - If
    ///   [`erc721::IErc721Receiver::on_erc721_received`] hasn't returned its
    ///   interface id or returned with an error.
    pub fn on_erc721_received(
        &mut self,
        _operator: Address,
        from: Address,
        token_id: U256,
        _data: &Bytes,
        erc721: &mut Erc721,
    ) -> Result<B32, Error> {
        let sender = self.vm().msg_sender();
        if self.underlying() != sender {
            return Err(Error::UnsupportedToken(ERC721UnsupportedToken {
                token: sender,
            }));
        }

        erc721._safe_mint(from, token_id, &vec![].into())?;

        Ok(RECEIVER_FN_SELECTOR)
    }

    /// Check [`IErc721Wrapper::underlying()`] for more information.
    #[must_use]
    pub fn underlying(&self) -> Address {
        self.underlying.get()
    }

    /// Mints wrapped tokens to cover any underlying tokens that would have been
    /// function that can be exposed with access control if desired.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `account` - The account to mint tokens to.
    /// * `token_id` - A mutable reference to the Erc20 contract.
    /// * `erc721` - Write access to an [`Erc721`] contract.
    ///
    /// # Errors
    ///
    /// * [`Error::Erc721FailedOperation`] - If the underlying token is not a
    ///   [`Erc721`]  or the contract fails to execute the call.
    /// * [`Error::IncorrectOwner`] - If the underlying token is not owned by
    ///   the contract.
    /// * [`Error::InvalidSender`] - If `token_id` already exists.
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    /// * [`Error::InvalidReceiver`] - If
    ///   [`erc721::IErc721Receiver::on_erc721_received`] hasn't returned its
    ///   interface id or returned with an error.
    fn _recover(
        &mut self,
        account: Address,
        token_id: U256,
        erc721: &mut Erc721,
    ) -> Result<U256, Error> {
        let underlying = Erc721Interface::new(self.underlying());

        let owner = underlying
            .owner_of(self.vm(), Call::new(), token_id)
            .map_err(|_| {
                Error::Erc721FailedOperation(Erc721FailedOperation {
                    token: self.underlying(),
                })
            })?;

        let contract_address = self.vm().contract_address();
        if owner != contract_address {
            return Err(erc721::Error::IncorrectOwner(
                erc721::ERC721IncorrectOwner {
                    sender: contract_address,
                    token_id,
                    owner,
                },
            )
            .into());
        }

        erc721._safe_mint(account, token_id, &vec![].into())?;

        Ok(token_id)
    }
}

