impl Erc721Enumerable {
    /// Function to add a token to this extension's
    /// ownership-tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Address representing the new owner of the given `token_id`.
    /// * `token_id` - ID of the token to be added to the tokens list of the
    ///   given address.
    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
    ///
    /// # Errors
    ///
    /// * [`erc721::Error::InvalidOwner`] - If owner address is
    ///   [`Address::ZERO`].
    pub fn _add_token_to_owner_enumeration(
        &mut self,
        to: Address,
        token_id: U256,
        erc721: &impl IErc721<Error = erc721::Error>,
    ) -> Result<(), erc721::Error> {
        let length = erc721.balance_of(to)? - uint!(1_U256);
        self.owned_tokens.setter(to).setter(length).set(token_id);
        self.owned_tokens_index.setter(token_id).set(length);

        Ok(())
    }

    /// Function to add a token to this extension's token
    /// tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` - ID of the token to be added to the tokens list.
    pub fn _add_token_to_all_tokens_enumeration(&mut self, token_id: U256) {
        let index = self.total_supply();

        self.all_tokens_index.setter(token_id).set(index);
        self.all_tokens.push(token_id);
    }

    /// Function to remove a token from this extension's
    /// ownership-tracking data structures.
    ///
    /// Note that while the token is not assigned a new owner,
    /// the `self.owned_tokens_index` mapping is NOT updated:
    /// this allows for  gas optimizations e.g.
    /// when performing a transfer operation (avoiding double writes).
    ///
    /// This has O(1) time complexity, but alters the order
    /// of the `self.owned_tokens` array.

item.aggregated_output:
    /// Destroys a `value` amount of tokens of type `id` from `from`.
    ///
    /// Re-export of [`Erc1155::_burn`].
    #[allow(clippy::missing_errors_doc)]
    pub fn _burn(
        &mut self,
        from: Address,
        id: U256,
        value: U256,
    ) -> Result<(), erc1155::Error> {
        self._do_burn(from, vec![id], vec![value])
    }

    /// Batched version of [`Self::_burn`].
    ///
    /// Re-export of [`Erc1155::_burn_batch`].
    #[allow(clippy::missing_errors_doc)]
    pub fn _burn_batch(
        &mut self,
        from: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), erc1155::Error> {
        self._do_burn(from, ids, values)
    }
}

impl Erc1155Supply {
    /// Extended version of [`Erc1155::_update`] that updates the supply of
    /// tokens.
    ///
    /// NOTE: The ERC-1155 acceptance check is not performed in this function.
    /// See [`Self::_update_with_acceptance_check`] instead.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account of the sender.
    /// * `to` - Account of the recipient.
    /// * `token_ids` - Array of all token id.
    /// * `values` - Array of all amount of tokens to be supplied.
    ///
    /// # Errors
    ///
    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
    ///   equal to length of `values`.
    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
    ///   the balance of the `from` account.
    ///
    /// # Events
    ///
    /// * [`erc1155::TransferSingle`] - If the arrays contain one element.
    /// * [`erc1155::TransferBatch`] - If the arrays contain more than one
    ///   element.
    ///
    /// # Panics
    ///
    /// * If updated balance and/or supply exceeds [`U256::MAX`], may happen
    ///   during the `mint` operation.
    fn _update(
        &mut self,
        from: Address,
        to: Address,
        token_ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), erc1155::Error> {
        self.erc1155._update(from, to, token_ids.clone(), values.clone())?;

        if from.is_zero() {
            for (&token_id, &value) in token_ids.iter().zip(values.iter()) {
                self.total_supply.setter(token_id).add_assign_checked(
                    value,
                    "should not exceed `U256::MAX` for `total_supply`",
                );
            }

            let total_mint_value = values.iter().sum();
            self.total_supply_all.add_assign_checked(
                total_mint_value,
                "should not exceed `U256::MAX` for `total_supply_all`",
            );
        }

        if to.is_zero() {
            for (token_id, &value) in token_ids.into_iter().zip(values.iter()) {
                /*
                 * SAFETY: Overflow not possible:
                 * values[i] <= balance_of(from, token_ids[i]) <=
                 * total_supply(token_ids[i])
                 */
                self.total_supply.setter(token_id).sub_assign_unchecked(value);
            }

            let total_burn_value: U256 = values.into_iter().sum();
            /*
             * SAFETY: Overflow not possible:
             * total_burn_value = sum_i(values[i]) <=
             * sum_i(total_supply(ids[i])) <= total_supply_all
             */
            self.total_supply_all.sub_assign_unchecked(total_burn_value);
        }
        Ok(())
    }

    fn _update_with_acceptance_check(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), erc1155::Error> {
        self._update(from, to, ids.clone(), values.clone())?;

        if !to.is_zero() {
            self.erc1155._check_on_erc1155_received(
                self.vm().msg_sender(),
                from,
                to,
                erc1155::Erc1155ReceiverData::new(ids, values),
                data.to_vec().into(),
            )?;
        }

        Ok(())
    }

    fn _do_mint(
        &mut self,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), erc1155::Error> {
        if to.is_zero() {
            return Err(erc1155::Error::InvalidReceiver(
                erc1155::ERC1155InvalidReceiver { receiver: to },
            ));
        }
        self._update_with_acceptance_check(
            Address::ZERO,
            to,
            ids,
            values,
            data,
        )?;
        Ok(())
    }

    fn _do_burn(
        &mut self,
        from: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), erc1155::Error> {
        if from.is_zero() {
            return Err(erc1155::Error::InvalidSender(
                erc1155::ERC1155InvalidSender { sender: from },
            ));
        }
        self._update_with_acceptance_check(
            from,
            Address::ZERO,
            ids,
            values,
            &vec![].into(),
        )?;
        Ok(())
    }

    fn do_safe_transfer_from(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), erc1155::Error> {
        if to.is_zero() {
            return Err(erc1155::Error::InvalidReceiver(
        ids: Vec<U256>,
        values: Vec<U256>,
        data: Bytes,
    ) -> Result<(), Self::Error> {
        self.authorize_transfer(from)?;
        self.do_safe_transfer_from(from, to, ids, values, &data)
    }
}

