            if last_key == key {
                self._index_mut(pos - uint!(1_U256)).value.set(value);
            } else {
                self._unchecked_push(key, value);
            }
            Ok((last_value, value))
        } else {
            self._unchecked_push(key, value);
            Ok((S::Value::ZERO, value))
        }
