#![cfg(feature = "e2e")]
#[path = "../../devnet_test_support.rs"]
mod devnet_test_support;

use crate::devnet_test_support::{
    constructor, receipt, send, watch, Account, Receipt, Revert,
};
use abi::{Erc1967Example, UUPSProxyErc20Example};
use alloy::primitives::Bytes;
use alloy::sol_types::SolCall;
use alloy_sol_types::SolError;
use eyre::Result;

mod abi;

trait Deploy {
    async fn deploy_uups(&self) -> Result<Receipt>;
    async fn deploy_uups_new_version(&self) -> Result<Receipt>;
    async fn deploy_proxy(
        &self,
        implementation: alloy::primitives::Address,
        owner: alloy::primitives::Address,
    ) -> Result<Receipt>;
}

impl Deploy for Account {
    async fn deploy_uups(&self) -> Result<Receipt> {
        self.as_deployer()
            .with_constructor(constructor!(self.address()))
            .deploy()
            .await
    }

    async fn deploy_uups_new_version(&self) -> Result<Receipt> {
        self.as_deployer()
            .with_example_name("uups-proxy-new-version")
            .with_constructor(constructor!(self.address()))
            .deploy()
            .await
    }

    async fn deploy_proxy(
        &self,
        implementation: alloy::primitives::Address,
        owner: alloy::primitives::Address,
    ) -> Result<Receipt> {
        let data: Bytes = UUPSProxyErc20Example::initializeCall { owner }
            .abi_encode()
            .into();

        self.as_deployer()
            .with_example_name("erc1967")
            .with_constructor(constructor!(implementation, data.clone()))
            .deploy()
            .await
    }
}

#[tokio::test]
async fn v1_initializer_cannot_be_called_again_by_an_attacker() -> Result<()> {
    let alice = Account::new().await?;
    let bob = Account::new().await?;
    let logic = alice.deploy_uups().await?.contract_address;
    let proxy_address =
        alice.deploy_proxy(logic, alice.address()).await?.contract_address;
    let proxy = Erc1967Example::new(proxy_address, &bob.wallet);

    let error = send!(proxy.initialize(bob.address()))
        .expect_err("reinitialization should revert");

    assert!(error.reverted_with(UUPSProxyErc20Example::InvalidInitialization {}));
    let proxy = Erc1967Example::new(proxy_address, &alice.wallet);
    assert_eq!(alice.address(), proxy.owner().call().await?);

    Ok(())
}

#[tokio::test]
async fn v2_initializer_cannot_be_called_again_by_an_attacker() -> Result<()> {
    let alice = Account::new().await?;
    let bob = Account::new().await?;
    let logic = alice.deploy_uups().await?.contract_address;
    let proxy_address =
        alice.deploy_proxy(logic, alice.address()).await?.contract_address;
    let proxy = Erc1967Example::new(proxy_address, &alice.wallet);
    let new_logic =
        alice.deploy_uups_new_version().await?.contract_address;

    receipt!(proxy.upgradeToAndCall(new_logic, Bytes::new()))?;

    let proxy = Erc1967Example::new(proxy_address, &bob.wallet);
    let error = send!(proxy.initialize(bob.address()))
        .expect_err("reinitialization should revert");

    assert!(error.reverted_with(UUPSProxyErc20Example::InvalidInitialization {}));
    let proxy = Erc1967Example::new(proxy_address, &alice.wallet);
    assert_eq!(alice.address(), proxy.owner().call().await?);

    Ok(())
}

#[tokio::test]
async fn set_version_remains_idempotent() -> Result<()> {
    let alice = Account::new().await?;
    let logic = alice.deploy_uups().await?.contract_address;
    let proxy_address =
        alice.deploy_proxy(logic, alice.address()).await?.contract_address;
    let proxy = UUPSProxyErc20Example::new(proxy_address, &alice.wallet);

    watch!(proxy.setVersion())?;
    watch!(proxy.setVersion())?;

    let proxy = Erc1967Example::new(proxy_address, &alice.wallet);
    assert_eq!(alice.address(), proxy.owner().call().await?);

    Ok(())
}

