/// Configurable cargo-stylus deployer.
pub struct Deployer {
    rpc_url: String,
    constructor: Option<Constructor>,
    example_name: Option<String>,
}

impl Deployer {
    /// Add constructor arguments to this deployment.
    #[must_use]
    pub fn with_constructor(mut self, constructor: Constructor) -> Self {
        self.constructor = Some(constructor);
        self
    }

    /// Deploy the `*-example` package associated with a named example.
    #[must_use]
    pub fn with_example_name(mut self, example_name: &str) -> Self {
        self.example_name = Some(format!("{example_name}-example"));
        self
    }

    /// Deploy the current example through cargo-stylus.
    pub async fn deploy(&self) -> eyre::Result<Receipt> {
        let package_name = match &self.example_name {
            Some(name) => name.clone(),
            None => package_name_for_current_package()?,
        };
        self.deploy_package(&package_name).await
    }

    async fn deploy_package(
        &self,
        package_name: &str,
    ) -> eyre::Result<Receipt> {
        static NEXT_SALT: AtomicU64 = AtomicU64::new(1);

        // cargo-stylus runs in a separate process and cannot invalidate the
        // Alloy provider's cached nonce. Use a one-shot signer for deployment
        // transactions so later calls through the test account stay in sync.
        let deployer = PrivateKeySigner::random();
        fund_address(&self.rpc_url, deployer.address(), DEPLOYER_FUNDING_WEI)
            .await?;
        let private_key = alloy::hex::encode(deployer.to_bytes());

        let workspace = workspace_root()?;

        let salt = NEXT_SALT.fetch_add(1, Ordering::Relaxed);
        let salt = format!("0x{:064x}", salt);
        let mut command = Command::new("cargo");
        command
            .args(["stylus", "deploy"])
            .arg("--no-verify")
            .args(["--contract", package_name])
            .args(["--endpoint", &self.rpc_url])
            .args(["--private-key", &private_key])
            .args([
                "--deployer-address",
                &env::var(DEPLOYER_ADDRESS)
                    .unwrap_or_else(|_| DEFAULT_DEPLOYER_ADDRESS.to_owned()),
            ])
            .args(["--deployer-salt", &salt])
            .env("CARGO_TERM_COLOR", "never");

        if let Some(constructor) = &self.constructor {
            command.arg("--constructor-args").args(&constructor.args);
        }

        let temporary_directory = workspace.join("target/stylus-tmp");
        std::fs::create_dir_all(&temporary_directory)?;
        let output = command
            .current_dir(&workspace)
            // cargo-stylus creates its temporary Dockerfile under TMPDIR.
            // Keeping it inside the workspace avoids macOS file-sharing
            // failures when Docker BuildKit reads tempfile from /private/tmp.
            .env("TMPDIR", temporary_directory)
            .output()
            .context("failed to execute cargo stylus deploy")?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        let output_text = format!("{stdout}\n{stderr}");
        if !output.status.success() {
            let details = &output_text;
            if self.constructor.is_some()
                && (details.contains("ContractInitializationError")
                    || contains_selector(
                        &details,
                        &CONTRACT_INITIALIZATION_ERROR_SELECTOR,
                    ))
            {
                return Err(eyre::Report::new(ContractInitializationError));
            }
            eyre::bail!("cargo stylus deploy failed:\n{details}");
        }

        let address = value_after_label(&output_text, "deployed code at address:")
            .ok_or_else(|| {
                eyre::eyre!(
                    "cargo stylus output did not contain a deployed address:\n{output_text}"
                )
            })?;
        let contract_address = Address::from_str(&address)?;
        let transaction_hash = value_after_label(
            &output_text,
            "deployment tx hash:",
        )
        .ok_or_else(|| {
            eyre::eyre!(
                "cargo stylus output did not contain a deployment transaction hash:\n{output_text}"
            )
        })?;
        let transaction_hash = TxHash::from_str(&transaction_hash)?;

        let provider =
            ProviderBuilder::new().connect_http(Url::from_str(&self.rpc_url)?);
        let inner = provider
            .get_transaction_receipt(transaction_hash)
            .await?
    Ok(gas)
}

/// Deploys a stylus contract, activating if needed.
pub async fn deploy(
    contract: &Contract,
    config: &DeploymentConfig,
    provider: &(impl Provider + WalletProvider),
) -> Result<(), DeploymentError> {
    let status = check_contract(contract, None, &config.check, provider).await?;
    let from_address = provider.default_signer_address();
    debug!(@grey, "sender address: {}", from_address.debug_lavender());
    let data_fee = status.suggest_fee() + config.constructor_value;

    if let ContractStatus::Ready { .. } = status {
        // check balance early
        let balance = provider
            .get_balance(from_address)
            .await
            .map_err(|_| DeploymentError::FailedToGetBalance)?;
        if balance < data_fee {
            return Err(DeploymentError::NotEnoughFunds {
                from_address,
                balance,
                data_fee,
            });
        }
    }

    if let Code::Fragments(fragments) = status.code() {
        let arb_owner_public = precompiles::arb_owner_public(provider);
        let max_fragment_count = arb_owner_public
            .getMaxStylusContractFragments()
            .call()
            .await
            // Failing this call likely means the chain does not support fragments (old ArbOS)
            .map_err(|_| DeploymentError::ContractTooLarge)?;
        if fragments.fragment_count() > max_fragment_count as usize {
            return Err(DeploymentError::ContractTooLarge);
        }
    }

    let constructor = get_constructor_signature(contract.package.name.as_str())
        .map_err(|_| ReadConstructorFailure)?;

    let req = match &constructor {
        None => match status.code() {
            Code::Contract(contract) => DeploymentRequest::new(
                from_address,
                contract.as_slice(),
                config.max_fee_per_gas_gwei,
            ),
            Code::Fragments(fragments) => {
                let root =
                    deploy_fragments(fragments, status.wasm().len() as u32, config, provider)
                        .await?;
                DeploymentRequest::new(from_address, root.as_slice(), config.max_fee_per_gas_gwei)
            }
        },
        Some(constructor) => {
            if constructor.state_mutability != Payable && !config.constructor_value.is_zero() {
                return Err(InvalidConstructor(
                    "attempting to send Ether to non-payable constructor".to_string(),
                ));
            }
            if config.constructor_args.len() != constructor.inputs.len() {
                return Err(InvalidConstructor(format!(
                    "mismatch number of constructor arguments (want {:?} ({}); got {})",
                    constructor.inputs,
                    constructor.inputs.len(),
                    config.constructor_args.len(),
                )));
            }

            let code = match status.code() {
                Code::Contract(contract) => contract.0.clone(),
                Code::Fragments(fragments) => {
                    deploy_fragments(fragments, status.wasm().len() as u32, config, provider)
                        .await?
                        .0
                }
            };
            let tx_calldata = parse_tx_calldata(
                &code,
                constructor,
                config.constructor_value,
                config.constructor_args.clone(),
                config.deployer_salt,
                &provider,
            )
            .await
            .map_err(|err| InvalidConstructor(err.to_string()))?;

            DeploymentRequest::new_with_args(
                from_address,
                config.deployer_address,
                data_fee,
                tx_calldata,
                config.max_fee_per_gas_gwei,
            )
        }
    };

    let receipt = req.exec(&provider).await?;

    let contract_addr = match &constructor {
        None => receipt
            .contract_address
            .ok_or(NoContractAddress("in receipt".to_string())),
        Some(_) => get_address_from_receipt(&receipt),
    }?;

    info!(@grey, "deployed code at address: {}", contract_addr.debug_lavender());
    debug!(@grey, "gas used: {}", format_gas(receipt.gas_used.into()));
