  ! rg -Fq 'flags = ["--enable-bulk-memory", "-O3"]' Stylus.toml; then
  printf 'scripts/build-wasm-artifacts.sh must match Stylus.toml.\n' >&2
  exit 1
fi

target_directory="$(cargo metadata --no-deps --format-version 1 | \
