        let err = contract
            .sender(alice)
            .token_of_owner_by_index(alice, token_idx)
            .expect_err("should return Error::OutOfBoundsIndex");

        assert!(matches!(err, Error::OutOfBoundsIndex(ERC721OutOfBoundsIndex {
                owner,
                index
            }) if owner == alice && index == token_idx
        ));
    }

