    let invalid_beacon_address = alice
        .as_deployer()
        .with_constructor(constructor!(no_code_address))
        .deploy()
        .await?
        .contract_address;
    let target_address = alice
        .as_deployer()
        .with_constructor(constructor!(implementation))
        .deploy()
        .await?
        .contract_address;

