    let amounts = vec![MAX_BATCH_SIZE + uint!(1_U96)];
    let err = alice
        .as_deployer()
        .with_constructor(ctr(&receivers, &amounts))
        .deploy()
        .await
        .expect_err("should not mint consecutive");

